/**
 * Public, bilingual content model for Jason Liao's academic portfolio.
 *
 * This module intentionally contains only visitor-facing copy. It does not
 * expose editorial notes, source locations, privacy reviews, or deployment
 * metadata. English canonical routes are stored once; `/zh` routes are
 * generated by `routeForLocale`.
 */

export type Locale = "en" | "zh";
export type Maturity =
  | "verified"
  | "reported"
  | "implemented_smoke_tested"
  | "in_progress"
  | "target"
  | "not_applicable";
export type Tier = "S" | "A" | "B" | "C";
export type AcademicStage = "university" | "high_school" | "pre_high_school" | "other";
export type ContentKind =
  | "page"
  | "research"
  | "project"
  | "coursework"
  | "honor"
  | "leadership"
  | "teaching_service"
  | "writing"
  | "personal"
  | "experience";

export interface LocalizedText {
  en: string;
  zh: string;
}

export interface LocalizedMetric {
  value: string;
  label: LocalizedText;
  context?: LocalizedText;
}

export interface LocalizedTable {
  headers: LocalizedText[];
  rows: LocalizedText[][];
}

export interface ContentSection {
  id: string;
  heading: LocalizedText;
  body?: LocalizedText;
  bullets?: LocalizedText[];
  metrics?: LocalizedMetric[];
  table?: LocalizedTable;
}

export interface ContentEntity {
  id: string;
  kind: ContentKind;
  route: string | null;
  title: LocalizedText;
  eyebrow: LocalizedText;
  summary: LocalizedText;
  card: LocalizedText;
  detail: LocalizedText;
  sections: ContentSection[];
  relatedRoutes: string[];
  category: string;
  tier?: Tier;
  maturity: Maturity;
  featured?: boolean;
  localOnly?: boolean;
  dateLabel?: LocalizedText;
  tags?: string[];
  stage?: AcademicStage;
}

export interface ResolvedMetric {
  value: string;
  label: string;
  context?: string;
}

export interface ResolvedSection {
  id: string;
  heading: string;
  body?: string;
  bullets?: string[];
  metrics?: ResolvedMetric[];
  table?: { headers: string[]; rows: string[][] };
}

export interface ResolvedPage {
  id: string;
  kind: ContentKind;
  locale: Locale;
  route: string;
  canonicalRoute: string;
  title: string;
  eyebrow: string;
  summary: string;
  card: string;
  detail: string;
  sections: ResolvedSection[];
  relatedRoutes: string[];
  category: string;
  tier?: Tier;
  maturity: Maturity;
  featured?: boolean;
  dateLabel?: string;
  tags: string[];
}

const stagePriority: Record<AcademicStage, number> = {
  university: 0,
  other: 1,
  high_school: 2,
  pre_high_school: 3,
};

const tierPriority: Record<Tier, number> = { S: 0, A: 1, B: 2, C: 3 };

const latestYear = (entity: ContentEntity): number => {
  const years = entity.dateLabel?.en.match(/(?:19|20)\d{2}/g)?.map(Number) ?? [];
  return years.length ? Math.max(...years) : 0;
};

/**
 * The public portfolio foregrounds university work, then current/general
 * context, followed by high-school and earlier foundations. Tier and recency
 * only decide order inside the same educational stage.
 */
export const compareContentEntities = (a: ContentEntity, b: ContentEntity): number => {
  const stageDifference = stagePriority[a.stage ?? "other"] - stagePriority[b.stage ?? "other"];
  if (stageDifference) return stageDifference;

  const tierDifference = tierPriority[a.tier ?? "C"] - tierPriority[b.tier ?? "C"];
  if (tierDifference) return tierDifference;

  return latestYear(b) - latestYear(a);
};

const t = (en: string, zh: string): LocalizedText => ({ en, zh });

const categoryInZh: Record<string, string> = {
  Core: "核心頁面",
  Education: "學歷",
  "Academic Record": "學業紀錄",
  Honors: "榮譽與競賽",
  Research: "研究",
  Projects: "工程專案",
  Writing: "寫作與紀錄",
  Leadership: "領導",
  Teaching: "教學",
  "Science Outreach": "科學推廣",
  Service: "服務",
  "Cross-Cultural Support": "跨文化支持",
  Campus: "校園參與",
  Personal: "個人經歷",
  Experience: "經歷",
  Governance: "內容治理",
  Mathematics: "數學",
  "Mathematics & Computation": "數學與計算",
  "Mechanics & Dynamics": "力學與動力學",
  "Mechanics, Dynamics & Control": "力學、動力學與控制",
  Computation: "計算",
  Experiments: "實驗",
  "Experiments & Design": "實驗與設計",
  "Design & Systems": "設計與系統",
  "Design & Manufacturing": "設計與製造",
};

const bilingualCategory = (category: string): LocalizedText =>
  t(category, categoryInZh[category] ?? category);

export const localizedCategory = (category: string, locale: Locale): string =>
  bilingualCategory(category)[locale];

const section = (
  id: string,
  headingEn: string,
  headingZh: string,
  bodyEn?: string,
  bodyZh?: string,
  bullets: LocalizedText[] = [],
  metrics: LocalizedMetric[] = [],
  table?: LocalizedTable,
): ContentSection => ({
  id,
  heading: t(headingEn, headingZh),
  ...(bodyEn && bodyZh ? { body: t(bodyEn, bodyZh) } : {}),
  ...(bullets.length ? { bullets } : {}),
  ...(metrics.length ? { metrics } : {}),
  ...(table ? { table } : {}),
});

const metric = (
  value: string,
  labelEn: string,
  labelZh: string,
  contextEn?: string,
  contextZh?: string,
): LocalizedMetric => ({
  value,
  label: t(labelEn, labelZh),
  ...(contextEn && contextZh ? { context: t(contextEn, contextZh) } : {}),
});

export const routeForLocale = (route: string, locale: Locale): string => {
  if (locale === "en") return route;
  return route === "/" ? "/zh" : `/zh${route}`;
};

const page = (
  id: string,
  route: string,
  title: LocalizedText,
  eyebrow: LocalizedText,
  summary: LocalizedText,
  sections: ContentSection[],
  relatedRoutes: string[],
): ContentEntity => ({
  id,
  kind: "page",
  route,
  title,
  eyebrow,
  summary,
  card: summary,
  detail: summary,
  sections,
  relatedRoutes,
  category: "Core",
  maturity: "verified",
});

