const courseworkFromSeed = (seed: CourseworkSeed): ContentEntity => ({
  id: seed.id,
  kind: "coursework",
  route: seed.route,
  title: seed.title,
  eyebrow: bilingualCategory(seed.category),
  summary: seed.card,
  card: seed.card,
  detail: seed.card,
  sections: [
    section("question-theory", "Question & theory", "問題與理論", seed.focus.en, seed.focus.zh),
    section("method-validation", "Method & validation", "方法與驗證", seed.validation.en, seed.validation.zh),
    section("output", "Results & documentation", "成果與文件", seed.output.en, seed.output.zh),
  ],
  relatedRoutes: seed.relatedRoutes ?? [],
  category: seed.category,
  tier: seed.featured ? "A" : "B",
  maturity: seed.maturity ?? "verified",
  featured: seed.featured ?? false,
  stage: "university",
  tags: [seed.category, ...(seed.tags ?? [])],
});

export const coursework: ContentEntity[] = courseworkSeeds.map(courseworkFromSeed);

