const caseSourceRoutes = [
  "/research/redrhex",
  "/research/geometry-covering",
  "/projects/aero-carrier",
  "/projects/jarvis",
  "/projects/lkas",
  "/projects/inventor-system-integration",
  "/projects/polar-arm",
  "/academics/numerical-analysis",
  "/academics/intermediate-dynamics",
  "/academics/engineering-mathematics",
  "/academics/mechanical-laboratory-ii",
  "/academics/linear-algebra-fft",
] as const;

const sourceEntities = [...events, ...coursework];

export const cases: ContentEntity[] = caseSourceRoutes.map((route) => {
  const source = sourceEntities.find((entity) => entity.route === route);
  if (!source) throw new Error(`Missing case source for ${route}`);
  return {
    ...source,
    sections: caseSectionsByRoute[route] ?? source.sections,
    detail: caseSectionsByRoute[route]
      ? t(
          caseSectionsByRoute[route].map((item) => item.body?.en).filter(Boolean).join("\n\n"),
          caseSectionsByRoute[route].map((item) => item.body?.zh).filter(Boolean).join("\n\n"),
        )
      : source.detail,
    featured: true,
  };
});

export const autobiographyEntries: ContentEntity[] = autobiographies.map((article) => ({
  id: article.id,
  kind: "writing",
  route: article.canonicalRoute,
  title: article.title,
  eyebrow: t("Full autobiography", "自傳全文"),
  summary: article.summary,
  card: article.card,
  detail: article.card,
  sections: [],
  relatedRoutes: [
    "/about",
    "/personal",
    "/writing",
    ...autobiographies
      .filter((candidate) => candidate.id !== article.id)
      .map((candidate) => candidate.canonicalRoute),
  ],
  category: "Writing",
  tier: "A",
  maturity: "verified",
  featured: true,
  dateLabel: t("Complete text", "完整全文"),
  tags: ["autobiography", "personal essay", "longform", "life story"],
  stage: "university",
}));

/**
 * Public route precedence is deliberate:
 * 1. fixed core pages;
 * 2. complete longform autobiographies;
 * 3. expanded case studies;
 * 4. remaining coursework;
 * 5. remaining events.
 *
 * This ensures a case-study projection wins over its compact event record,
 * while retaining one canonical route and one resolved public entity.
 */
const publicRouteIndex = new Map<string, ContentEntity>();
for (const entity of [...corePages, ...autobiographyEntries, ...cases, ...coursework, ...events]) {
  if (!entity.route || entity.localOnly) continue;
  if (!publicRouteIndex.has(entity.route)) publicRouteIndex.set(entity.route, entity);
}

export const allContent: ContentEntity[] = [...publicRouteIndex.values()];
export const allPublicRoutes: string[] = [...publicRouteIndex.keys()];

const stripQueryAndHash = (path: string): string =>
  (path.split(/[?#]/, 1)[0] || "/").trim() || "/";

const normalizeCanonicalPath = (inputPath: string): string => {
  let path = stripQueryAndHash(inputPath);
  if (!path.startsWith("/")) path = `/${path}`;
  path = path.replace(/\/{2,}/g, "/");

  // `/en` is a legacy alias. `/zh` is the current Traditional Chinese prefix.
  if (path === "/en" || path === "/zh") return "/";
  if (path.startsWith("/en/")) path = path.slice(3);
  if (path.startsWith("/zh/")) path = path.slice(3);

  if (path.length > 1) path = path.replace(/\/+$/, "");
  return path.toLowerCase();
};

const localeFromPath = (inputPath: string, fallback: Locale): Locale => {
  const path = stripQueryAndHash(inputPath).toLowerCase();
  if (path === "/zh" || path.startsWith("/zh/")) return "zh";
  if (path === "/en" || path.startsWith("/en/")) return "en";
  return fallback;
};

const resolveSection = (item: ContentSection, locale: Locale): ResolvedSection => ({
  id: item.id,
  heading: item.heading[locale],
  ...(item.body ? { body: item.body[locale] } : {}),
  ...(item.bullets ? { bullets: item.bullets.map((bullet) => bullet[locale]) } : {}),
  ...(item.metrics
    ? {
        metrics: item.metrics.map((itemMetric) => ({
          value: itemMetric.value,
          label: itemMetric.label[locale],
          ...(itemMetric.context ? { context: itemMetric.context[locale] } : {}),
        })),
      }
    : {}),
  ...(item.table
    ? {
        table: {
          headers: item.table.headers.map((header) => header[locale]),
          rows: item.table.rows.map((row) => row.map((cell) => cell[locale])),
        },
      }
    : {}),
});

const resolveEntity = (entity: ContentEntity, locale: Locale): ResolvedPage => {
  if (!entity.route) throw new Error(`Cannot resolve local-only entity ${entity.id}`);
  return {
    id: entity.id,
    kind: entity.kind,
    locale,
    route: routeForLocale(entity.route, locale),
    canonicalRoute: entity.route,
    title: entity.title[locale],
    eyebrow: entity.eyebrow[locale],
    summary: entity.summary[locale],
    card: entity.card[locale],
    detail: entity.detail[locale],
    sections: entity.sections.map((item) => resolveSection(item, locale)),
    relatedRoutes: entity.relatedRoutes.map((route) => routeForLocale(route, locale)),
    category: localizedCategory(entity.category, locale),
    ...(entity.tier ? { tier: entity.tier } : {}),
    maturity: entity.maturity,
    ...(entity.featured !== undefined ? { featured: entity.featured } : {}),
    ...(entity.dateLabel ? { dateLabel: entity.dateLabel[locale] } : {}),
    tags: entity.tags ?? [],
  };
};

export const getEntityByCanonicalRoute = (
  path: string,
): ContentEntity | undefined => publicRouteIndex.get(normalizeCanonicalPath(path));

export const getEntityById = (id: string): ContentEntity | undefined =>
  allContent.find((entity) => entity.id === id);

export const getPageByPath = (
  path: string,
  locale: Locale = "en",
): ResolvedPage | undefined => {
  const effectiveLocale = localeFromPath(path, locale);
  const entity = getEntityByCanonicalRoute(path);
  return entity ? resolveEntity(entity, effectiveLocale) : undefined;
};

export const getCollection = (
  category: string,
  locale: Locale = "en",
): ResolvedPage[] =>
  allContent
    .filter((entity) => entity.category === category && entity.route)
    .sort(compareContentEntities)
    .map((entity) => resolveEntity(entity, locale));

// Fail closed if a future edit silently drops a governed public record.
if (events.length !== 59) throw new Error(`Expected 59 events after removing the standalone midterm-score item, received ${events.length}`);
if (events.filter((entity) => entity.route && !entity.localOnly).length !== 58) {
  throw new Error("Expected 58 public events and one local-only event");
}
const allowedOtherEventIds = new Set(["event-045", "event-046"]);
const unclassifiedEvents = events.filter(
  (entity) => entity.stage === "other" && !allowedOtherEventIds.has(entity.id),
);
if (unclassifiedEvents.length) {
  throw new Error(`Unclassified event stages: ${unclassifiedEvents.map((entity) => entity.id).join(", ")}`);
}
if (coursework.some((entity) => entity.stage !== "university")) {
  throw new Error("Every coursework record must be classified as university work");
}
if (coursework.length !== 15) {
  throw new Error(`Expected 15 coursework records, received ${coursework.length}`);
}
if (new Set(allPublicRoutes).size !== allPublicRoutes.length) {
  throw new Error("Duplicate canonical route in resolved public content");
}
for (const entity of allContent) {
  if (!entity.route?.startsWith("/") || entity.route.startsWith("/zh") || entity.route.startsWith("/en")) {
    throw new Error(`Invalid English canonical route for ${entity.id}`);
  }
  for (const field of [entity.title, entity.eyebrow, entity.summary, entity.card, entity.detail]) {
    if (!field.en.trim() || !field.zh.trim()) {
      throw new Error(`Incomplete bilingual public copy for ${entity.id}`);
    }
  }
  for (const contentSection of entity.sections) {
    if (!contentSection.heading.en.trim() || !contentSection.heading.zh.trim()) {
      throw new Error(`Incomplete bilingual section heading for ${entity.id}`);
    }
    if (contentSection.body && (!contentSection.body.en.trim() || !contentSection.body.zh.trim())) {
      throw new Error(`Incomplete bilingual section body for ${entity.id}`);
    }
  }
}
